  values(v_release_id, 10, 'g10_st3', 10, 4, 'category', 'Phân loại đúng nhóm', 'Lựa chọn cách truyền thông tin phòng bệnh virus dựa trên nguồn đáng tin cậy.', '{"categories":["Nguồn đáng tin cậy","Nguồn cần kiểm chứng"],"items":["Cơ quan y tế","Tài liệu chính thức","Tin đồn không nguồn","Bài đăng ẩn danh"],"hint":"“Cơ quan y tế” thuộc nhóm “Nguồn đáng tin cậy”."}'::jsonb, '{"value":[{"name":"Cơ quan y tế","catIndex":0},{"name":"Tài liệu chính thức","catIndex":0},{"name":"Tin đồn không nguồn","catIndex":1},{"name":"Bài đăng ẩn danh","catIndex":1}],"explanation":"Cơ quan y tế thuộc nhóm Nguồn đáng tin cậy; Tài liệu chính thức thuộc nhóm Nguồn đáng tin cậy; Tin đồn không nguồn thuộc nhóm Nguồn cần kiểm chứng; Bài đăng ẩn danh thuộc nhóm Nguồn cần kiểm chứng."}'::jsonb, '[{"source":"SGK Sinh học 10 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 26. Thực hành: Điều tra một số bệnh do virus và tuyên truyền phòng bệnh"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 10, 'g10_st3', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Lựa chọn cách truyền thông tin phòng bệnh virus dựa trên nguồn đáng tin cậy.', '{"textWithBlanks":"Khi truyền thông phòng bệnh, nên ghi rõ [blank] thông tin.","bankWords":["nguồn","tin đồn","màu nền"],"hint":"Từ cần chọn gồm 1 tiếng và bắt đầu bằng chữ “n”."}'::jsonb, '{"value":"nguồn","explanation":"Từ đúng là “nguồn”."}'::jsonb, '[{"source":"SGK Sinh học 10 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 26. Thực hành: Điều tra một số bệnh do virus và tuyên truyền phòng bệnh"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
